await page.goto(`${ORANGE_HRM}/pim/viewEmployeeList`);
await page.getByPlaceholder("Type for hints...").first().fill(lastName);
await page.getByRole("button", { name: "Search" }).click();
await page.waitForLoadState("networkidle");
console.log("rows found:", await page.locator("div.oxd-table-row--clickable").count());

// The sibling axis: find the cell whose text IS the last name, go up to its
// parent (the actual table-cell div — the text node's own parent is just an
// inner wrapper with no siblings), then step sideways to the last cell in
// that row.
const actionsCell = page.locator(
  `xpath=//div[text()='${lastName}']/parent::div/following-sibling::div[last()]`,
);
console.log("buttons in actions cell:", await actionsCell.locator("button").count());

await actionsCell.locator("button").first().click(); // pencil = edit
await page.waitForURL("**/pim/viewPersonalDetails/**");
console.log("on personal details:", page.url());

// Measured against this live, shared demo: the "Successfully Updated" toast can
// fire a beat before the save has actually landed. Reload and check; if it
// hasn't landed, save again. This is real behaviour on a public sandbox, not a
// bug in the locators above.
const updatedLastName = lastName + "Updated";
let savedValue = "";
for (let attempt = 1; attempt <= 3 && savedValue !== updatedLastName; attempt++) {
  const box = page.getByPlaceholder("Last Name").first();
  await box.fill("");
  await box.fill(updatedLastName);
  await box.blur();
  // Two buttons on this page match the role name "Save" — .first() is the
  // Personal Details form's own button, verified live before writing this.
  await page.getByRole("button", { name: "Save" }).first().click();
  console.log(`attempt ${attempt} toast:`, await page.locator("p.oxd-text--toast-message").first().textContent());

  await page.reload();
  await page.waitForLoadState("networkidle");
  savedValue = await page.getByPlaceholder("Last Name").first().inputValue();
}
console.log("value after reload:", savedValue);

// contains(), not an exact match on either name: the list might still show
// the OLD last name at this point, or it might have caught up to the new
// one. The random id is in there either way, so contains() finds the row
// regardless of which one is currently rendered.
await page.goto(`${ORANGE_HRM}/pim/viewEmployeeList`);
await page.getByPlaceholder("Type for hints...").first().fill(idPart);
await page.getByRole("button", { name: "Search" }).click();
await page.waitForLoadState("networkidle");
console.log("rows found by idPart:", await page.locator("div.oxd-table-row--clickable").count());

const actionsCellForDelete = page.locator(
  `xpath=//div[contains(text(), '${idPart}')]/parent::div/following-sibling::div[last()]`,
);
await actionsCellForDelete.locator("button").last().click(); // trash = delete
await page.getByText("Are you sure you want to continue?").waitFor();
await page.getByRole("button", { name: "Yes, Delete" }).click();
console.log("delete toast:", await page.locator("p.oxd-text--toast-message").first().textContent());

await page.goto(`${ORANGE_HRM}/pim/viewEmployeeList`);
await page.getByPlaceholder("Type for hints...").first().fill(idPart);
await page.getByRole("button", { name: "Search" }).click();
await page.waitForLoadState("networkidle");
console.log("rows found after delete:", await page.locator("div.oxd-table-row--clickable").count());

await browser.close();

