import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

const specPath = "week2/generated/day4-employee-crud.spec.ts";

await writeProjectFile(specPath, `// Week 2, Day 4 — the sibling-axis locator, exercised end to end: create an
// employee, find its row by last name (not by position), update it, verify
// the change persisted, then delete it and prove the row is really gone.
//
// OrangeHRM's demo is a shared public sandbox, so this test cleans up after
// itself — the same rule week7 follows for demoqa.com.
//
// Three measured quirks shape this file, all real behaviour on a public,
// shared, occasionally-loaded demo — not bugs in the locators:
//   1. A button click can silently do nothing (an overlay steals the click
//      for a moment). clickAndExpectToast() retries the click itself.
//   2. The "Successfully Updated" toast can fire before the save has
//      actually landed — verified by reloading the record, retried too.
//   3. After a rename, the Employee List can keep showing the OLD last name
//      for a while. The row is re-found for deletion with contains() on the
//      random id, which is true of the row whichever name is showing.
import { test, expect } from "@playwright/test";

const ORANGE_HRM = "https://opensource-demo.orangehrmlive.com/web/index.php";

test("create, update, and delete an employee found by the sibling axis", async ({ page }) => {
  test.setTimeout(120000);

  async function clickAndExpectToast(buttonName: string, expectedText: string) {
    for (let attempt = 1; attempt <= 3; attempt++) {
      await page.getByRole("button", { name: buttonName }).first().click();
      try {
        await expect(page.locator("p.oxd-text--toast-message")).toHaveText(expectedText, {
          timeout: 6000,
        });
        return;
      } catch (err) {
        if (attempt === 3) throw err;
        console.log(\`  "\${buttonName}" click #\${attempt} produced no toast, retrying\`);
      }
    }
  }

  await page.goto(\`\${ORANGE_HRM}/auth/login\`);
  await page.getByPlaceholder("Username").fill("Admin");
  await page.getByPlaceholder("Password").fill("admin123");
  await page.getByRole("button", { name: "Login" }).click();
  await page.waitForURL("**/dashboard/index");

  const idPart = Math.floor(Math.random() * 100000).toString();
  const lastName = "Verify" + idPart;
  await page.goto(\`\${ORANGE_HRM}/pim/addEmployee\`);
  await page.getByPlaceholder("First Name").fill("Verify");
  await page.getByPlaceholder("Last Name").fill(lastName);
  await clickAndExpectToast("Save", "Successfully Saved");
  await page.waitForURL("**/pim/viewPersonalDetails/**");

  await page.goto(\`\${ORANGE_HRM}/pim/viewEmployeeList\`);
  await page.getByPlaceholder("Type for hints...").first().fill(lastName);
  await page.getByRole("button", { name: "Search" }).click();
  await page.waitForLoadState("networkidle");
  await expect(page.locator("div.oxd-table-row--clickable")).toHaveCount(1, { timeout: 10000 });

  const actionsCell = page.locator(
    \`xpath=//div[text()='\${lastName}']/parent::div/following-sibling::div[last()]\`,
  );
  await actionsCell.locator("button").first().click();
  await page.waitForURL("**/pim/viewPersonalDetails/**");

  const updatedLastName = lastName + "Updated";
  let persisted = false;
  for (let attempt = 1; attempt <= 3 && !persisted; attempt++) {
    const lastNameBox = page.getByPlaceholder("Last Name").first();
    await lastNameBox.waitFor({ state: "visible" });
    await lastNameBox.fill("");
    await lastNameBox.fill(updatedLastName);
    await lastNameBox.blur();
    await clickAndExpectToast("Save", "Successfully Updated");
    await page.reload();
    await page.waitForLoadState("networkidle");
    const value = await page.getByPlaceholder("Last Name").first().inputValue();
    persisted = value === updatedLastName;
    if (!persisted) console.log(\`  update attempt \${attempt}: got "\${value}", retrying\`);
  }
  expect(persisted).toBe(true);

  await page.goto(\`\${ORANGE_HRM}/pim/viewEmployeeList\`);
  await page.getByPlaceholder("Type for hints...").first().fill(idPart);
  await page.getByRole("button", { name: "Search" }).click();
  await page.waitForLoadState("networkidle");
  await expect(page.locator("div.oxd-table-row--clickable")).toHaveCount(1, { timeout: 10000 });

  const actionsCell2 = page.locator(
    \`xpath=//div[contains(text(), '\${idPart}')]/parent::div/following-sibling::div[last()]\`,
  );
  await actionsCell2.locator("button").last().click();
  await expect(page.getByText("Are you sure you want to continue?")).toBeVisible();
  await clickAndExpectToast("Yes, Delete", "Successfully Deleted");

  await page.goto(\`\${ORANGE_HRM}/pim/viewEmployeeList\`);
  await page.getByPlaceholder("Type for hints...").first().fill(idPart);
  await page.getByRole("button", { name: "Search" }).click();
  await page.waitForLoadState("networkidle");
  await expect(page.locator("div.oxd-table-row--clickable")).toHaveCount(0, { timeout: 10000 });
  await expect(page.locator("span.oxd-text--span", { hasText: "No Records Found" })).toBeVisible();
});
`.trim());

await runSpec(specPath);

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// No test() calls here, so the runner never collects this file — just a helper.
// Not named *.spec.ts on purpose (week3/day3_2's rule: a helper file never
// carries the spec suffix, or the runner tries to execute it as a test).
await writeProjectFile("week2/generated/employee-list-helpers.ts", `// Week 2, Day 4 — shared actions for OrangeHRM's Add Employee / Employee List
// screens. Same pattern as registration-helpers.ts from Days 1-3: plain
// functions, not a class. A real page object (a \`class\` that never asserts)
// is coming formally in week 3 — this reaches for the simplest tool that
// already removes the repetition.
import type { Locator, Page } from "@playwright/test";

const ORANGE_HRM = "https://opensource-demo.orangehrmlive.com/web/index.php";

export async function addEmployee(page: Page, lastName: string): Promise<void> {
  await page.goto(\`\${ORANGE_HRM}/pim/addEmployee\`);
  await page.getByPlaceholder("First Name").fill("Verify");
  await page.getByPlaceholder("Last Name").fill(lastName);
  await page.getByRole("button", { name: "Save" }).click();
  await page.waitForURL("**/pim/viewPersonalDetails/**", { timeout: 15000 });
}

// The sibling axis: search for the known text, then walk sideways from it to
// the row's last cell — the one holding the edit/delete buttons. contains()
// rather than an exact match, so this still finds the row if a rename hasn't
// shown up in the list yet (see Day 4.2).
export async function findRow(page: Page, term: string): Promise<Locator> {
  await page.goto(\`\${ORANGE_HRM}/pim/viewEmployeeList\`);
  await page.getByPlaceholder("Type for hints...").first().fill(term);
  await page.getByRole("button", { name: "Search" }).click();
  await page.waitForLoadState("networkidle");
  return page.locator(
    \`xpath=//div[contains(text(), '\${term}')]/parent::div/following-sibling::div[last()]\`,
  );
}

export async function deleteEmployee(page: Page, term: string): Promise<void> {
  const actionsCell = await findRow(page, term);
  await actionsCell.locator("button").last().click(); // trash icon
  await page.getByText("Are you sure you want to continue?").waitFor();
  await page.getByRole("button", { name: "Yes, Delete" }).click();
}
`.trim());

